func (s *Server) writeHTML(
	w http.ResponseWriter,
	r *http.Request,
	head, body datapages.Component,
	writeBodyAttrs func(w http.ResponseWriter),
	writeBodySuffix func(w http.ResponseWriter),
) error {
	_, err := io.WriteString(w, `<!DOCTYPE html><html><head><meta charset="UTF-8"/>
		<script type="module" src="`+s.datastarJSSrc+`"></script>`)
	if err != nil {
		return err
	}
	if head != nil {
		if err := head.Render(r.Context(), w); err != nil {
			return err
		}
	}
	if _, err := io.WriteString(w, "</head><body "); err != nil {
		return err
	}
	if writeBodyAttrs != nil {
		writeBodyAttrs(w)
	}
	if _, err := io.WriteString(w, ">"); err != nil {
		return err
	}
	if body != nil {
		if err := body.Render(r.Context(), w); err != nil {
			return err
		}
	}
	if writeBodySuffix != nil {
		if _, err := io.WriteString(w, "<template "); err != nil {
			return err
		}
		writeBodySuffix(w)
		if _, err := io.WriteString(w, "></template>"); err != nil {
			return err
		}
	}
	_, err = io.WriteString(w, "</body></html>")
	return err
}

func (s *Server) handleStreamRequest(
	w http.ResponseWriter, r *http.Request,
	subjects []string,
	onOpen func(
		streamID uint64,
		sse *datastar.ServerSentEventGenerator,
	) error,
	onClose func(streamID uint64),
	fn func(
		streamID uint64,
		sse *datastar.ServerSentEventGenerator,
		ch <-chan msgbroker.Message,
	),
) {
	if !s.checkIsDSReq(w, r) {
		return
	}

	streamID := s.streamSeq.Add(1)
	sse := datastar.NewSSE(w, r, datastar.WithCompression())
	mSSEConnections.Inc()
	defer mSSEConnections.Dec()
	start := time.Now()

	ctx := r.Context()
	sub, err := s.messageBroker.Subscribe(ctx, s.messageBrokerMetrics, subjects...)
	if err != nil {
		s.httpErrIntern(w, r, sse, "subscribing to message broker", err)
		return
	}

	subC := sub.C()
	if onOpen != nil {
		if err := onOpen(streamID, sse); err != nil {
			sub.Close()
			s.httpErrIntern(w, r, sse, "handling stream open hook", err)
			return
		}
	}
	go func() {
		select {
		case <-r.Context().Done():
			mSSEDisconnects.WithLabelValues("client").Inc()
		case <-s.shutdownCh:
			mSSEDisconnects.WithLabelValues("shutdown").Inc()
		}
		mSSEConnectionDuration.Observe(time.Since(start).Seconds())
		sub.Close()
		if onClose != nil {
			// Not the goroutine net/http recovers.
			defer func() {
				if rec := recover(); rec != nil {
					s.logErr("recovering panic in stream close hook",
						fmt.Errorf("%v\n%s", rec, debug.Stack()))
				}
			}()
			onClose(streamID)
		}
	}()

	fn(streamID, sse, subC)
}

